return ['domain'=>'taxopress-pron%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11 ? 0 : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1 : 2);','language'=>'ru_RU','project-id-version'=>'TaxoPress Pro 3.51.0','pot-creation-date'=>'2026-07-22T18:23:43+00:00','po-revision-date'=>'2026-07-22 18:37+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['TaxoPress Pro'=>'TaxoPress Pro','https://wordpress.org/plugins/simple-tags/'=>'https://wordpress.org/plugins/simple-tags/','TaxoPress allows you to create and manage Tags, Categories, and all your WordPress taxonomy terms.'=>'TaxoPress позволяет вам создавать и управлять метками, категориями и всеми вашими терминами таксономии WordPress.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','License key'=>'Ключ лицензии','Status'=>'Статус','Your license key provides access to updates and support.'=>'Ваш ключ лицензии предоставляет доступ к обновлениям и поддержке.','Activate License'=>'Активировать лицензию','Synonyms'=>'Синонимы','This feature allows you to associate additional words with each term. For example, "website" can have synonyms such as "websites", "web site", and "web pages".'=>'Эта функция позволяет вам связывать дополнительные слова с каждым термином. Например, "веб-сайт" может иметь синонимы, такие как "веб-сайты", "веб сайт" и "веб-страницы".','Linked Terms'=>'Связанные термины','This feature allows you to connect terms. When the main term or any of these terms are added to the post, all the other terms will be added also.'=>'Эта функция позволяет вам связывать термины. Когда основной термин или любой из этих терминов добавляется в запись, все другие термины также будут добавлены.','Shortcode Name'=>'Имя шорткода','Add'=>'Добавить','Enter the shortcode name without [ ] or parameters.'=>'Введите имя шорткода без [ ] или параметров.','Search Block'=>'Поиск блока','Search...'=>'Поиск...','Search and select blocks.'=>'Искать и выбирать блоки.','Element tag'=>'Тег элемента','Add Element'=>'Добавить элемент','New Element'=>'Новый элемент','OpenAI is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'OpenAI — это внешняя служба, которая может сканировать ваш контент и предлагать соответствующие термины. %1sНажмите здесь для получения подробной информации%2s.','False'=>'Ложь','True'=>'Истина','This will automatically add new terms from the OpenAI service. Before use, please test carefully using the preview feature.'=>'Это автоматически добавит новые термины из сервиса OpenAI. Перед использованием, пожалуйста, тщательно протестируйте с помощью функции предварительного просмотра.','Enable OpenAI'=>'Включить OpenAI','API Key'=>'API-ключ','Enter your OpenAI API Key.'=>'Введите ваш API-ключ OpenAI.','gpt-3.5-turbo'=>'gpt-3.5-turbo','gpt-4o-mini'=>'gpt-4o-mini','gpt-4o'=>'gpt-4o','chatgpt-4o-latest'=>'chatgpt-4o-latest','gpt-5'=>'gpt-5','gpt-5-mini'=>'gpt-5-mini','gpt-5-nano'=>'gpt-5-nano','o3-mini'=>'o3-mini','o1-mini'=>'o1-mini','o1'=>'o1','OpenAI Models'=>'Модели OpenAI','Some models availability depends on your subscription and access.'=>'Некоторые модели доступны в зависимости от вашей подписки и доступа.','Show Term Post Count'=>'Показать количество постов по термину','This will show the number of posts attached to the terms.'=>'Это покажет количество постов, прикрепленных к терминам.','Cache Results'=>'Кэшировать результаты','By caching the results locally, new API requests will not be made unless the post title or content changes. This saves API usage.'=>'Кэшируя результаты локально, новые API-запросы не будут отправляться, если заголовок или содержание поста не изменится. Это экономит использование API.','OpenAI Prompt (Beta)'=>'OpenAI Запрос (Бета)','%1s Click here for prompt documentation. %2s'=>'%1s Нажмите здесь для документации по запросам. %2s','OpenAI Max Tokens'=>'Максимальные токены OpenAI','Maximum tokens for OpenAI response. You can increase this when using {site} placeholder with many terms.'=>'Максимальное количество токенов для ответа OpenAI. Вы можете увеличить это значение, используя плейсхолдер {site} с множеством терминов.','IBM Watson is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'IBM Watson - это внешний сервис, который может сканировать ваш контент и предлагать соответствующие термины. %1sНажмите здесь для получения подробностей%2s.','This will automatically add new terms from the IBM Watson service. Before use, please test carefully using the preview feature.'=>'Это автоматически добавит новые термины из сервиса IBM Watson. Перед использованием, пожалуйста, тщательно протестируйте, используя функцию предварительного просмотра.','Enable IBM Watson'=>'Включить IBM Watson','API URL'=>'URL API','Enter your IBM Watson API URL.'=>'Введите ваш URL API IBM Watson.','Enter your IBM Watson API Key.'=>'Введите ваш API-ключ IBM Watson.','This integration is no longer actively supported. If you still need to use it, you can enable it in the Legacy AI Sources settings.'=>'Эта интеграция больше не поддерживается активно. Если вам все еще нужно ее использовать, вы можете включить ее в настройках устаревших AI источников.','Dandelion is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'Dandelion - это внешний сервис, который может сканировать ваш контент и предлагать соответствующие термины. %1sНажмите здесь для получения подробностей%2s.','This will automatically add new terms from the Dandelion service. Before use, please test carefully using the preview feature.'=>'Это автоматически добавит новые термины из сервиса Dandelion. Перед использованием, пожалуйста, тщательно протестируйте, используя функцию предварительного просмотра.','Enable Dandelion'=>'Включить Dandelion','API Token'=>'Токен API','Enter your Dandelion API Key.'=>'Введите ваш ключ API Dandelion.','API Confidence Value'=>'API Confidence Value','Choose a value between 0 and 1. A high value such as 0.8 will provide a few, accurate suggestions. A low value such as 0.2 will produce more suggestions, but they may be less accurate.'=>'Выберите значение от 0 до 1. Высокое значение, такое как 0.8, обеспечит несколько точных предложений. Низкое значение, такое как 0.2, даст больше предложений, но они могут быть менее точными.','LSEG / Refinitiv is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'LSEG / Refinitiv - это внешний сервис, который может сканировать ваш контент и предлагать релевантные термины. %1sНажмите здесь для получения подробностей%2s.','This will automatically add new terms from the LSEG / Refinitiv service. Before use, please test carefully using the preview feature.'=>'Это автоматически добавит новые термины из сервиса LSEG / Refinitiv. Перед использованием, пожалуйста, внимательно протестируйте с помощью функции предварительного просмотра.','Enable LSEG / Refinitiv'=>'Включить LSEG / Refinitiv','Enter your LSEG / Refinitiv API Key.'=>'Введите ваш ключ API LSEG / Refinitiv.','Regular Expressions'=>'Регулярные выражения','Use Regular Expressions to change how Auto Terms analyzes your posts. This works for terms added when posts are saved or added via the "Schedule" feature.'=>'Используйте регулярные выражения, чтобы изменить то, как Auto Terms анализирует ваши посты. Это работает для терминов, добавленных при сохранении постов или добавленных через функцию "Расписание".','Regex code'=>'Код Regex','Example: <code>/\\b({term})\\b/i</code> will match the whole word while <code>/({term})/i</code> will match at any location even if it\'s part of another word. <code>{term}</code> will be replaced with the term name before the regex action.'=>'Пример: <code>/\\b({term})\\b/i</code> будет соответствовать целому слову, в то время как <code>/({term})/i</code> будет соответствовать в любом месте, даже если это часть другого слова. <code>{term}</code> будет заменено на имя термина перед выполнением действия regex.','Auto Terms successfully copied.'=>'Авто термины успешно скопированы.','Copy'=>'Копировать','Hourly'=>'Каждый час','Daily'=>'Ежедневно','Primary Term Name'=>'Имя основного термина','Secondary Term Name'=>'Имя вторичного термина','Primary Term Taxonomy'=>'Таксономия основного термина','Secondary Term Taxonomy'=>'Таксономия вторичного термина','Primary Term Post Count'=>'Количество постов основного термина','Secondary Term Post Count'=>'Количество записей с вторичным термином','Add primary term to posts with secondary term'=>'Добавить основной термин к записям с вторичным термином','Add secondary term to posts with primary term'=>'Добавить вторичный термин к записям с основным термином','Delete Relationship'=>'Удалить связь','Taxonomy'=>'taxonomy','Filter'=>'Фильтр','Error deleting linked term relationship.'=>'Ошибка при удалении связанного термина.','Linked terms deleted successfully.'=>'Связанные термины успешно удалены.','Linked term deleted successfully.'=>'Связанный термин успешно удален.','%d posts updated successfully.'=>'%d записей успешно обновлено.','0 post update.'=>'0 обновлений записи.','No linked terms found.'=>'Связанные термины не найдены.','Number of items per page'=>'Количество элементов на странице','This feature allows you to connect terms. When the primary or secondary term is added to a post, the other term can be added also.'=>'Эта функция позволяет связывать термины. Когда основной или вторичный термин добавляется к записи, другой термин также может быть добавлен.','Search results for &#8220;%s&#8221;'=>'Результаты поиска для &#8220;%s&#8221;','Search Terms'=>'Поисковые термины','Description here.'=>'Описание здесь.','Start typing to choose existing terms.'=>'Начните вводить, чтобы выбрать существующие термины.','These terms are linked to the main term. When the primary or secondary term is added to a post, the other term can be added also.'=>'Эти термины связаны с основным термином. Когда основной или вторичный термин добавляется к записи, другой термин также может быть добавлен.','The superscript %1$s indicates the linked term being the primary term, while %2$s is shown when the linked term is the secondary term. You can delete the relationship and re-add it from your preferred term edit screen to make them the primary term.'=>'Суперскрипт %1$s указывает, что связанный термин является основным термином, в то время как %2$s отображается, когда связанный термин является вторичным термином. Вы можете удалить связь и заново добавить ее на экране редактирования вашего предпочтительного термина, чтобы сделать их основным термином.','Term Synonyms'=>'Синонимы термина','Type the synonym name (comma-separated) and then click Enter or Return.'=>'Введите название синонима (разделенное запятыми) и затем нажмите Enter или Return.','If TaxoPress scans your content and finds a synonym, it will act as if it has found the main term.'=>'Если TaxoPress сканирует ваш контент и находит синоним, он будет действовать так, как будто нашел основной термин.','This synonym can\'t be added because %1$s is a term on this site.'=>'Этот синоним не может быть добавлен, потому что %1$s является термином на этом сайте.','These synonyms can\'t be added because %1$s are terms on this site.'=>'Эти синонимы не могут быть добавлены, потому что %1$s являются терминами на этом сайте.','This synonym can\'t be added because %1$s is already added to another term.'=>'Этот синоним не может быть добавлен, потому что %1$s уже добавлен к другому термину.','These synonyms can\'t be added because %1$s are already added to another term.'=>'Эти синонимы не могут быть добавлены, потому что %1$s уже добавлены к другому термину.','%1$s can\'t be added as a tag because %2$s is already used as a synonym.'=>'%1$s не может быть добавлен в качестве тега, потому что %2$s уже используется в качестве синонима.','Request status.'=>'Статус запроса.','Security error. Kindly reload this page and try again'=>'Ошибка безопасности. Пожалуйста, перезагрузите эту страницу и попробуйте еще раз','Default'=>'По умолчанию','Dropdown'=>'Выпадающий список','Checkbox'=>'Флажок','Taxonomy Display'=>'Отображение таксономии','Enable IBM Watson integration'=>'Включить интеграцию с IBM Watson','Show IBM Watson as an AI source for Auto Terms'=>'Показать IBM Watson в качестве источника ИИ для Авто терминов','Enable Dandelion integration'=>'Включить интеграцию с Dandelion','Show Dandelion as an AI source for Auto Terms.'=>'Показать Dandelion в качестве источника ИИ для Авто терминов.','Enable LSEG/Refinitiv integration'=>'Включить интеграцию с LSEG/Refinitiv','Show LSEG/Refinitiv as an AI source for Auto Terms'=>'Показать LSEG/Refinitiv в качестве источника ИИ для Авто терминов','Term successfully copied with metadata.'=>'Термин успешно скопирован с метаданными.','Copy with Metadata'=>'Копировать с метаданными']];